def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))

    # Find the small-color marker in a corner, then recolor the matching
    # non-background object indicated by its color.
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    marker = min((c for c in counts if c != bg), key=lambda c: counts[c])

    # The marker color is the color to paint the target object. In these
    # puzzles the target is the prominent object of the other non-background color.
    candidates = [c for c in counts if c not in (bg, marker)]
    if not candidates:
        return out
    target = max(candidates, key=lambda c: counts[c])

    # Find 4-connected target components and recolor the component with the
    # greatest area, preserving all other cells.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != target or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == target and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            comps.append(comp)
    if comps:
        comp = max(comps, key=len)
        for r, c in comp:
            out[r][c] = marker
    return out
